    }
    if (type === 'crc8') {
      let crc = 0;
      for (let i = from; i < to; i += 1) {
        crc ^= bytes[i] || 0;
        for (let bit = 0; bit < 8; bit += 1) {
          crc = (crc & 0x80) ? ((crc << 1) ^ 0x07) : (crc << 1);
          crc &= 0xFF;
        }
